import{_ as o,I as e,o as p,c,b6 as l,j as a,J as s,w as n,a as i}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"类 Dify 智能体平台开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/custom-dify-agent-platform/index.md","filePath":"zh-cn/stage-2/assignments/custom-dify-agent-platform/index.md"}'),b={name:"zh-cn/stage-2/assignments/custom-dify-agent-platform/index.md"},u={style:{margin:"32px 0"}};function k(g,t,f,m,_,E){const r=e("StepBar"),d=e("ClientOnly"),h=e("el-card");return p(),c("div",null,[t[2]||(t[2]=l('<h1 id="类-dify-智能体平台开发实战" tabindex="-1">类 Dify 智能体平台开发实战 <a class="header-anchor" href="#类-dify-智能体平台开发实战" aria-label="Permalink to “类 Dify 智能体平台开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD，从零完成一个模仿 Dify 核心体验的智能体平台。你将构建用户控制台、管理后台和平台后端，实现智能体管理、对话、日志和知识库等核心功能。</p><p>这是 Stage 2 的综合实战环节。与前面的单页面或单功能项目不同，这个项目要求你构建一个有&quot;平台感&quot;的 AI 产品——包含多角色、多模块、数据持久化和模型调用链路。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读并理解一份真实的 PRD，从中提取开发任务清单</li><li>设计智能体平台的页面架构和数据模型</li><li>实现智能体创建、对话、日志记录的完整链路</li><li>使用 AI 辅助完成平台型产品开发</li><li>完成端到端联调，交付一个可演示的 AI 平台原型</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个类 Dify 智能体平台，包含两个子系统：</p><table tabindex="0"><thead><tr><th>子系统</th><th>职责</th></tr></thead><tbody><tr><td><strong>用户控制台</strong></td><td>创建智能体、配置 Prompt、发起对话、查看日志、管理知识库</td></tr><tr><td><strong>管理后台</strong></td><td>查看用户数据、平台资源使用情况、调用统计</td></tr></tbody></table><p>后端需要支持以下核心能力：智能体管理、会话管理、消息存储、模型调用、调用日志记录、知识库接入。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/custom-dify-agent-platform/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',15)),a("div",u,[s(d,null,{default:n(()=>[s(r,{active:0,items:[{title:"需求分析",description:"阅读 PRD，明确页面、能力边界、鉴权、数据模型"},{title:"搭建骨架",description:"用 AI 生成用户控制台和管理后台骨架"},{title:"迭代开发",description:"逐模块补充智能体、对话、日志、知识库"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),t[3]||(t[3]=l(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>智能体、会话、日志、知识库哪些要进 MVP？</li><li>页面和路由清单是否拍板？</li><li>模型调用和日志记录的边界是什么？</li><li>多租户和复杂工作流是否先不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认系统架构" tabindex="-1">1.2 确认系统架构 <a class="header-anchor" href="#_1-2-确认系统架构" aria-label="Permalink to “1.2 确认系统架构”">​</a></h3><p>根据 PRD 梳理出系统的整体架构：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; app[&quot;用户控制台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;管理后台&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;鉴权&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; agent[&quot;智能体配置&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; chat[&quot;会话对话&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; llm[&quot;模型调用&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  chat --&gt; db[&quot;数据库&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; kb[&quot;知识库接入&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; logs[&quot;调用日志与平台概览&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  logs --&gt; db</span></span></code></pre></div><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成前端页面" tabindex="-1">2.1 生成前端页面 <a class="header-anchor" href="#_2-1-生成前端页面" aria-label="Permalink to “2.1 生成前端页面”">​</a></h3><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个类 Dify 智能体平台的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 用户侧包括：登录、智能体列表、智能体配置、对话页、日志页、知识库页</span></span>
<span class="line"><span>2. 后台侧包括：后台首页、用户概览、资源使用概览</span></span>
<span class="line"><span>3. 先只生成页面结构和假数据，不接真实接口</span></span>
<span class="line"><span>4. 风格要像现代 AI 平台</span></span></code></pre></div><h3 id="_2-2-验证页面结构" tabindex="-1">2.2 验证页面结构 <a class="header-anchor" href="#_2-2-验证页面结构" aria-label="Permalink to “2.2 验证页面结构”">​</a></h3><p>逐项检查：</p><ul><li>[ ] 用户控制台和管理后台入口是否分开</li><li>[ ] 智能体列表、配置、对话、日志、知识库页面是否完整</li><li>[ ] 管理后台首页、用户概览页面是否可访问</li><li>[ ] 假数据展示了基本的 UI 状态</li></ul><h2 id="第三部分-迭代开发" tabindex="-1">第三部分：迭代开发 <a class="header-anchor" href="#第三部分-迭代开发" aria-label="Permalink to “第三部分：迭代开发”">​</a></h2><h3 id="_3-1-按模块推进" tabindex="-1">3.1 按模块推进 <a class="header-anchor" href="#_3-1-按模块推进" aria-label="Permalink to “3.1 按模块推进”">​</a></h3><p>在骨架的基础上，按以下顺序逐模块补充功能：</p><ol><li><strong>鉴权</strong>：注册、登录、角色区分</li><li><strong>智能体管理</strong>：创建、编辑、删除、Prompt 配置</li><li><strong>对话功能</strong>：会话创建、消息收发、模型调用</li><li><strong>日志记录</strong>：耗时、token 用量、错误记录</li><li><strong>知识库接入</strong>（加分项）：文档上传、检索、结果注入</li><li><strong>管理后台</strong>：用户数据、资源使用、调用统计</li></ol><p>每完成一个模块，使用下表进行自检：</p><table tabindex="0"><thead><tr><th>检查项</th><th>验证方法</th></tr></thead><tbody><tr><td>页面一致性</td><td>页面数量、功能是否符合 PRD</td></tr><tr><td>接口闭环</td><td>agents、chat、logs、knowledge 接口是否完整</td></tr><tr><td>权限隔离</td><td>用户是否只能管理自己的 agent 和会话</td></tr><tr><td>数据一致性</td><td>messages、logs、documents 数据是否对得上</td></tr><tr><td>可演示性</td><td>是否能演示&quot;创建 agent → 对话 → 查看日志&quot;完整链路</td></tr></tbody></table><h3 id="_3-2-知识库接入-加分项" tabindex="-1">3.2 知识库接入（加分项） <a class="header-anchor" href="#_3-2-知识库接入-加分项" aria-label="Permalink to “3.2 知识库接入（加分项）”">​</a></h3><p>如果你想增加知识库能力，可以给每个智能体增加一个&quot;知识库开关&quot;：</p><ul><li>开启后先检索知识片段，再和用户问题一起发送给模型</li><li>关闭后按普通对话模式响应</li></ul><p>第一版不必追求复杂 RAG，只要有&quot;检索结果可见、调用链路可解释&quot;即可。</p><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>至少验证以下场景：</p><ul><li>注册 → 创建智能体 → 配置 Prompt → 发起对话 → 查看日志</li><li>管理员登录 → 查看用户数据 → 查看调用统计</li></ul><p>部署前检查：</p><ul><li>[ ] 所有核心接口都做了登录校验</li><li>[ ] 智能体归属权限检查通过</li><li>[ ] 会话记录、日志记录真实落库</li><li>[ ] 模型 Key 使用环境变量，不硬编码</li><li>[ ] 错误提示可在前端看到，不只打控制台</li></ul><h3 id="_4-2-部署" tabindex="-1">4.2 部署 <a class="header-anchor" href="#_4-2-部署" aria-label="Permalink to “4.2 部署”">​</a></h3><p>将项目部署到公网环境。部署教程参考：<a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a>、<a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a>。</p><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（智能体管理页、对话页、日志页、后台首页）</li><li>[ ] 60 秒演示视频（覆盖创建智能体 → 对话 → 查看日志）</li></ul><p>README 至少包含：项目简介、架构说明、技术栈、本地启动步骤、环境变量清单、接口说明。</p><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>平台完整度</td><td>agents / chat / logs 三页可用</td><td>有清晰导航与统一设计语言</td></tr><tr><td>业务闭环</td><td>可创建智能体并真实对话</td><td>支持多智能体切换与历史会话</td></tr><tr><td>数据与追踪</td><td>消息与调用日志可查询</td><td>有 token / 耗时统计看板</td></tr><tr><td>权限安全</td><td>仅登录用户可访问核心接口</td><td>资源归属校验完善</td></tr><tr><td>工程交付</td><td>可部署、可演示、README 清晰</td><td>接入知识库并可解释检索结果</td></tr></tbody></table><h2 id="提交前检查" tabindex="-1">提交前检查 <a class="header-anchor" href="#提交前检查" aria-label="Permalink to “提交前检查”">​</a></h2>`,40)),s(h,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:n(()=>[...t[0]||(t[0]=[a("div",{style:{"font-weight":"bold","font-size":"16px"}},"提交前最后看一眼",-1)])]),default:n(()=>[t[1]||(t[1]=a("ul",{style:{"list-style-type":"none","padding-left":"0"}},[a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 登录后可访问智能体管理、对话、日志页面")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 至少可以创建 1 个智能体并成功对话")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 每轮问答都能在数据库查到记录")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 调用失败时前端可见错误信息且日志已记录")])]),a("li",null,[a("label",null,[a("input",{type:"checkbox",disabled:""}),i(" 项目已部署，README 和演示视频齐全")])])],-1))]),_:1}),t[4]||(t[4]=l('<h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li></ul>',2))])}const x=o(b,[["render",k]]);export{P as __pageData,x as default};
